// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/readyz", wrapper.Ready)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/assistant-conversations/{conversationId}", wrapper.DeleteAssistantConversation)
	m.HandleFunc("GET "+options.BaseURL+"/v1/assistant-conversations/{conversationId}", wrapper.ReadAssistantConversation)
	m.HandleFunc("POST "+options.BaseURL+"/v1/assistant-messages", wrapper.AppendAssistantMessage)
	m.HandleFunc("POST "+options.BaseURL+"/v1/assistant-runs", wrapper.CreateAssistantRun)
	m.HandleFunc("GET "+options.BaseURL+"/v1/assistant-runs/{runId}", wrapper.ReadAssistantRun)
	m.HandleFunc("POST "+options.BaseURL+"/v1/assistant-runs/{runId}/cancel", wrapper.CancelAssistantRun)
	m.HandleFunc("GET "+options.BaseURL+"/v1/context-manifests/{versionHash}", wrapper.ReadContextManifest)
	m.HandleFunc("POST "+options.BaseURL+"/v1/context:resolve", wrapper.ResolveContext)
	m.HandleFunc("GET "+options.BaseURL+"/v1/entries", wrapper.ListEntries)
	m.HandleFunc("POST "+options.BaseURL+"/v1/entries", wrapper.CreateEntry)
	m.HandleFunc("GET "+options.BaseURL+"/v1/entries/{entryId}", wrapper.ReadEntry)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/entries/{entryId}", wrapper.UpdateEntry)
	m.HandleFunc("POST "+options.BaseURL+"/v1/entries/{entryId}/archive", wrapper.ArchiveEntry)
	m.HandleFunc("POST "+options.BaseURL+"/v1/entries/{entryId}/restore", wrapper.RestoreEntry)
	m.HandleFunc("GET "+options.BaseURL+"/v1/entries/{entryId}/revisions", wrapper.ListEntryRevisions)
	m.HandleFunc("GET "+options.BaseURL+"/v1/mappings", wrapper.ListMappings)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/mappings/{mappingId}", wrapper.RemoveMapping)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/mappings/{mappingId}", wrapper.PutMapping)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/mappings:reorder", wrapper.ReorderMappings)
	m.HandleFunc("POST "+options.BaseURL+"/v1/proposals/{proposalId}/approve", wrapper.ApproveProposal)
	m.HandleFunc("POST "+options.BaseURL+"/v1/proposals/{proposalId}/reject", wrapper.RejectProposal)
	m.HandleFunc("GET "+options.BaseURL+"/v1/task-budgets", wrapper.ListTaskBudgets)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/task-budgets/{taskId}", wrapper.PutTaskBudget)

	return m
}

